CREATE TABLE Students (
    student_id INT PRIMARY KEY,
    name VARCHAR(100),
    department_id INT FOREIGN KEY
);

void inorderTraversal(Node* root) {
    if (root != nullptr) {
        inorderTraversal(root->left);
        cout << root->data << " ";
        inorderTraversal(root->right);
    }
}
